-- ve-restaurant-guide, ve-pathways, ve-outreach-buckets, vegans-explore-initiative-business-certification: playbook rows and records for
-- 2026-11-04 (Sean: "splinter off the restaurant guide by itself"; the certification playbook; People built in BrandDesk).
-- Data only (ve_playbook_index, playbook_records), idempotent. The certification row and its 3 records, and the ve-outreach-buckets and ve-pathways row updates of this day, were applied through the connector; the ve-restaurant-guide row and the records below were held by the connector at wrap-up (2026-11-04) and are NOT confirmed applied: check before relying on them.

insert into ve_playbook_index (slug, brand_slug, title, goal, status, stage, next_action, owner, due_on, priority) values
('ve-restaurant-guide','vegans-explore','The Vegan Restaurant Guide',
 'A 100% Vegan restaurant that gets our email can open the Guide on its own business, run a free check, take the short survey and get in, with Liz telling it exactly what to do.',
 'waiting_on_sean',
 'Nov 4: Version 1 live on main (ed0e2db). Liz audio plays on the five visitor tabs (checked in a browser). A four-reviewer panel found the Overview does not say what to do. Recommendation written, nothing changed in the Guide yet. 100% Vegan restaurants only for now.',
 'Sean: approve or change Liz''s draft Overview line and the shorter front door (Overview, Your audit, What to expect, Get in; the rest after the survey; Test yourself cut). Then Logan builds it on a branch, shows 1440 and 390 screenshots, re-records Liz, and tests a real /go/bo- link with a test contact.',
 'Sean', null, 3)
on conflict (slug) do update set title=excluded.title, goal=excluded.goal, status=excluded.status, stage=excluded.stage, next_action=excluded.next_action, owner=excluded.owner, priority=excluded.priority, updated_at=now();

update ve_playbook_index set
  goal='Anyone gets in by email, the survey or the $11, and every person we reach sits in a campaign with a next step.',
  status='waiting_on_sean', owner='Sean',
  stage='Nov 4: the Restaurant Guide was split out as ve-restaurant-guide. People is built in HQ BrandDesk (work recorded under ve-outreach-buckets). Nothing sent, emails are drafts, no city on. Welcome Guide four-step and the Explore sorting hat come after the restaurant batch.',
  next_action='Logan, once ve-restaurant-guide is finished and Sean has said go on the engine change: stage the first 30 restaurants (Sean reads every email and where it was found, approves each send day, turns each city on).',
  updated_at=now()
where slug='ve-pathways';

insert into playbook_records (slug, brand_slug, kind, author, source, body)
select v.slug, 'vegans-explore', 'decision', 'Logan', 'text', v.body from (values
('ve-restaurant-guide','ve-restaurant-guide: split out of ve-pathways to finish the Guide on its own (Sean, 2026-11-04: "let''s splinter off the restaurant guide by itself, so we can just finish that development"). Scope for now: only 100% Vegan restaurants ("right now, we''re only focusing on 100% vegan restaurants"); Vegan-options restaurants go through the certification playbook (vegans-explore-initiative-business-certification). State: Version 1 live at /guides/vegan-restaurant-guide (main ed0e2db); personal link ?b=<code> opens it on the business, not yet tested with a real /go/bo- link. Liz''s door audio (overview, audit, featured, demo, join) was checked in a browser 2026-11-04: all five visitor tabs load and play with no errors; the member What''s next line was not tested; Pulse, Promotions and Test yourself have no recording; desktop only. Still open from Version 1: the four-step What''s next, the per-answer Can be shown switch, the Their story section, template-gate screenshots at 1440 and 390.'),
('ve-restaurant-guide','ve-restaurant-guide: front door recommendation after a four-reviewer panel (Sean, 2026-11-04, after hearing the Overview line: "it doesn''t tell me what to do... let''s determine if we really need all of this... we want to get people enrolled into the system, and then we can let the automation stuff do the rest"). The reviewers were AI personas reading the page text and a desktop screenshot, not real owners. Agreed 4 of 4: Overview, Your audit and Get in at the front door; The fixes, Pulse and Promotions behind it; Test yourself cut; the Overview has about 14 competing things and should have 3. Split: Try the demo and Claim your page. Recommended: front door = Overview, Your audit, What to expect, Get in; after the survey = The fixes, Pulse, Claim your page, Try the demo, Promotions, My list; one button (Run my free check); drop the lock tags and the "not a pitch" line; move the $11, points and Partner plan talk out of the first visit; no promise about survey length (unknown). Strategist: run the audit by itself from the personal link and show three findings (not checked whether the link does this today). Draft Liz line awaiting Sean: Hi, I''m Liz. Thank you for what you do. Here is what to do. Step one, tap Run my free check and see how your place looks online. It takes about a minute. Step two, take the short survey. That makes you a member, and the rest of this Guide opens: your fixes, your page, and what is coming. It''s free, no card, and you can stop any time. Not locked; re-record only after Sean approves the words.'),
('ve-pathways','ve-pathways: the Restaurant Guide is split out as ve-restaurant-guide (Sean, 2026-11-04). ve-pathways keeps the three doors, campaigns on people, the Welcome Guide and the batches of outreach; People in BrandDesk is recorded under ve-outreach-buckets (built in HQ on claude/vibrant-knuth-1nds2h, engine change on claude/laughing-dirac-udxp3j not deployed). The first 30 restaurants are staged only after the Restaurant Guide is finished. Nothing has been sent and no city is on.')
) as v(slug, body)
where not exists (select 1 from playbook_records r where r.slug = v.slug and left(r.body, 90) = left(v.body, 90));
